-- project/0001_init.sql: consolidated end-state schema for the project database (ADR-0049).
-- Generated by wipe-and-adopt from the legacy 45-migration history; no data migration.

CREATE TABLE applications (
    id         TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name       TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);;

CREATE TABLE approvals (
    id         TEXT PRIMARY KEY,
    thread_id  TEXT NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    tool       TEXT NOT NULL,
    args       TEXT NOT NULL DEFAULT '{}',
    status     TEXT NOT NULL DEFAULT 'pending'
                   CHECK (status IN ('pending', 'approved', 'denied')),
    created_at TEXT NOT NULL,
    decided_at TEXT
);;

CREATE TABLE artifacts (
    id             TEXT PRIMARY KEY,
    task_id        TEXT REFERENCES tasks(id) ON DELETE CASCADE,
    sha256         TEXT NOT NULL,
    media_type     TEXT NOT NULL DEFAULT 'application/octet-stream',
    size           INTEGER NOT NULL,
    kind           TEXT NOT NULL CHECK (kind IN ('input', 'output')),
    name           TEXT NOT NULL DEFAULT '',
    created_at     TEXT NOT NULL
);;

CREATE TABLE assets (
    id             TEXT PRIMARY KEY,
    application_id TEXT NOT NULL REFERENCES applications(id) ON DELETE CASCADE,
    type           TEXT NOT NULL CHECK (type IN (
                       'source_repo', 'cloud_deployment', 'infrastructure', 'document', 'correspondence')),
    location       TEXT NOT NULL,
    sensitivity    TEXT NOT NULL DEFAULT 'private' CHECK (sensitivity IN ('open_source', 'private')),
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL
);;

CREATE TABLE context_items (
    id             TEXT PRIMARY KEY,
    project_id     TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    application_id TEXT REFERENCES applications(id) ON DELETE SET NULL,
    type           TEXT NOT NULL CHECK (type IN ('document', 'email', 'chat', 'note')),
    name           TEXT NOT NULL,
    artifact_id    TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,
    created_at     TEXT NOT NULL
);;

CREATE TABLE corpus_chunks (
    id          TEXT PRIMARY KEY,
    project_id  TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    source_kind TEXT NOT NULL,             -- 'context' (corpus doc) | 'kb' (knowledge-base entry)
    source_id   TEXT NOT NULL,             -- the context_item / kb_entry id
    source_name TEXT NOT NULL DEFAULT '',  -- human label (doc name / KB title) for the retrieval result
    chunk_index INTEGER NOT NULL,
    text        TEXT NOT NULL,
    embedding   BLOB NOT NULL,             -- []float32 little-endian
    dim         INTEGER NOT NULL,
    model       TEXT NOT NULL DEFAULT '',  -- the embedding backend id (provenance)
    created_at  TEXT NOT NULL
);;

CREATE TABLE coverage_observations (
    project_id     TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    item_id        TEXT NOT NULL,
    observation_id TEXT NOT NULL REFERENCES observations(id) ON DELETE CASCADE,
    created_at     TEXT NOT NULL,
    PRIMARY KEY (project_id, item_id, observation_id)
);;

CREATE TABLE disposition_rules (
    id            TEXT PRIMARY KEY,
    project_id    TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    capability_id TEXT NOT NULL DEFAULT '',
    when_json     TEXT NOT NULL DEFAULT '{}', -- attribute match {key: value}
    min_severity  TEXT NOT NULL DEFAULT '',
    action        TEXT NOT NULL CHECK (action IN ('finding', 'investigate', 'review')),
    priority      INTEGER NOT NULL DEFAULT 0,
    created_at    TEXT NOT NULL
);;

CREATE TABLE external_links (
    id           TEXT PRIMARY KEY,
    finding_id   TEXT NOT NULL REFERENCES findings(id) ON DELETE CASCADE,
    integration  TEXT NOT NULL,
    external_id  TEXT NOT NULL,
    external_url TEXT NOT NULL DEFAULT '',
    created_at   TEXT NOT NULL,
    UNIQUE (finding_id, integration)
);;

CREATE TABLE finding_observations (
    finding_id     TEXT NOT NULL REFERENCES findings(id) ON DELETE CASCADE,
    observation_id TEXT NOT NULL REFERENCES observations(id) ON DELETE CASCADE,
    PRIMARY KEY (finding_id, observation_id)
);;

CREATE TABLE findings (
    id             TEXT PRIMARY KEY,
    application_id TEXT REFERENCES applications(id) ON DELETE SET NULL,
    title          TEXT NOT NULL,
    severity       TEXT NOT NULL DEFAULT 'medium'
                       CHECK (severity IN ('info', 'low', 'medium', 'high', 'critical')),
    status         TEXT NOT NULL DEFAULT 'open'
                       CHECK (status IN ('open', 'confirmed', 'remediated', 'accepted', 'false_positive')),
    description    TEXT NOT NULL DEFAULT '',
    cwe            TEXT NOT NULL DEFAULT '',
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL
);;

CREATE TABLE http_exchanges (
    id               TEXT PRIMARY KEY,
    project_id       TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name             TEXT NOT NULL DEFAULT '',
    origin           TEXT NOT NULL DEFAULT 'replay' CHECK (origin IN ('replay', 'proxy')),
    method           TEXT NOT NULL,
    url              TEXT NOT NULL,
    request_headers  TEXT NOT NULL DEFAULT '',
    request_body     TEXT NOT NULL DEFAULT '',
    status           INTEGER,
    response_headers TEXT NOT NULL DEFAULT '',
    response_body    TEXT NOT NULL DEFAULT '',
    duration_ms      INTEGER,
    created_at       TEXT NOT NULL,
    sent_at          TEXT
, egress TEXT NOT NULL DEFAULT '');;

CREATE TABLE integration_configs (
    id          TEXT PRIMARY KEY,
    project_id  TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    integration TEXT NOT NULL,          -- connector name: jira | defectdojo
    base_url    TEXT NOT NULL DEFAULT '',
    project_key TEXT NOT NULL DEFAULT '', -- tracker-side scope selector (e.g. a DefectDojo test id)
    credential  TEXT NOT NULL DEFAULT '', -- vault secret NAME (never a value)
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL,
    UNIQUE (project_id, integration)
);;

CREATE TABLE integration_imports (
    id             TEXT PRIMARY KEY,
    project_id     TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    integration    TEXT NOT NULL,
    external_id    TEXT NOT NULL,
    observation_id TEXT NOT NULL REFERENCES observations(id) ON DELETE CASCADE,
    imported_at    TEXT NOT NULL,
    UNIQUE (project_id, integration, external_id)
);;

CREATE TABLE investigation_vulns (
    id               TEXT PRIMARY KEY,
    investigation_id TEXT NOT NULL REFERENCES investigations(id) ON DELETE CASCADE,
    project_id       TEXT NOT NULL,
    vuln_id          TEXT NOT NULL, -- a CVE or GHSA advisory id
    created_at       TEXT NOT NULL,
    UNIQUE (project_id, vuln_id)
);;

CREATE TABLE investigations (
    id             TEXT PRIMARY KEY,
    project_id     TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    application_id TEXT REFERENCES applications(id) ON DELETE SET NULL,
    observation_id TEXT NOT NULL UNIQUE REFERENCES observations(id) ON DELETE CASCADE,
    title          TEXT NOT NULL,
    status         TEXT NOT NULL DEFAULT 'open'
                       CHECK (status IN ('open', 'investigating', 'resolved', 'dismissed')),
    thread_id      TEXT REFERENCES threads(id) ON DELETE SET NULL, -- the agent investigation thread, once run
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL
);;

CREATE TABLE messages (
    id         TEXT PRIMARY KEY,
    thread_id  TEXT NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
    seq        INTEGER NOT NULL,
    role       TEXT NOT NULL, -- system | user | assistant
    content    TEXT NOT NULL,
    created_at TEXT NOT NULL, tool_calls TEXT NOT NULL DEFAULT '', tool_call_id TEXT NOT NULL DEFAULT '', tool_error INTEGER NOT NULL DEFAULT 0,
    UNIQUE (thread_id, seq)
);;

CREATE TABLE methodology_coverage (
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    item_id    TEXT NOT NULL,
    status     TEXT NOT NULL CHECK (status IN ('not_started', 'in_progress', 'covered', 'not_applicable')),
    note       TEXT NOT NULL DEFAULT '',
    updated_at TEXT NOT NULL,
    PRIMARY KEY (project_id, item_id)
);;

CREATE TABLE notifications (
    id         TEXT PRIMARY KEY,
    kind       TEXT NOT NULL,
    title      TEXT NOT NULL,
    body       TEXT NOT NULL DEFAULT '',
    project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,
    link       TEXT NOT NULL DEFAULT '',
    read       INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL
);;

CREATE TABLE observations (
    id           TEXT PRIMARY KEY,
    task_id      TEXT REFERENCES tasks(id) ON DELETE CASCADE,
    artifact_id  TEXT REFERENCES artifacts(id) ON DELETE SET NULL,
    origin       TEXT NOT NULL CHECK (origin IN ('tool', 'thread', 'human')),
    review_state TEXT NOT NULL DEFAULT 'unreviewed'
                     CHECK (review_state IN ('unreviewed', 'confirmed', 'rejected')),
    title        TEXT NOT NULL,
    detail       TEXT NOT NULL DEFAULT '',
    severity     TEXT NOT NULL DEFAULT 'info'
                     CHECK (severity IN ('info', 'low', 'medium', 'high', 'critical')),
    rule_id      TEXT NOT NULL DEFAULT '',
    location     TEXT NOT NULL DEFAULT '',
    created_at   TEXT NOT NULL
, project_id TEXT REFERENCES projects(id), attributes TEXT NOT NULL DEFAULT '', fingerprint TEXT NOT NULL DEFAULT '');;

CREATE TABLE plan_steps (
    id          TEXT PRIMARY KEY,
    plan_id     TEXT NOT NULL REFERENCES plans(id) ON DELETE CASCADE,
    seq         INTEGER NOT NULL,
    step_key    TEXT NOT NULL,
    profile     TEXT NOT NULL,
    instruction TEXT NOT NULL,
    depends_on  TEXT NOT NULL DEFAULT '', -- comma-separated step keys
    status      TEXT NOT NULL DEFAULT 'pending', -- pending | running | done | failed | skipped
    result      TEXT NOT NULL DEFAULT '',
    error       TEXT NOT NULL DEFAULT ''
, gate INTEGER NOT NULL DEFAULT 0, gate_approved INTEGER NOT NULL DEFAULT 0);;

CREATE TABLE plans (
    id          TEXT PRIMARY KEY,
    project_id  TEXT NOT NULL DEFAULT '',
    playbook_id TEXT NOT NULL,
    goal        TEXT NOT NULL DEFAULT '',
    status      TEXT NOT NULL DEFAULT 'running', -- running | done | failed
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);;

CREATE TABLE playbook_run_tasks (
    run_id  TEXT NOT NULL REFERENCES playbook_runs(id) ON DELETE CASCADE,
    task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    seq     INTEGER NOT NULL,
    PRIMARY KEY (run_id, task_id)
);;

CREATE TABLE playbook_runs (
    id          TEXT PRIMARY KEY,
    playbook_id TEXT NOT NULL,
    asset_id    TEXT REFERENCES assets(id) ON DELETE SET NULL,
    actor       TEXT NOT NULL DEFAULT '',
    status      TEXT NOT NULL DEFAULT 'running' CHECK (status IN ('running', 'succeeded', 'failed')),
    created_at  TEXT NOT NULL,
    finished_at TEXT
);;

CREATE TABLE project_methodologies (
    project_id     TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    methodology_id TEXT NOT NULL,
    created_at     TEXT NOT NULL,
    PRIMARY KEY (project_id, methodology_id)
);;

CREATE TABLE project_targets (
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    target_id  TEXT NOT NULL,
    PRIMARY KEY (project_id, target_id)
);;

CREATE TABLE projects (
    id              TEXT PRIMARY KEY,
    organization_id TEXT,
    group_id        TEXT,
    name            TEXT NOT NULL,
    status          TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'archived')),
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL
);;

CREATE TABLE proxy_rules (
    id         TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    enabled    INTEGER NOT NULL DEFAULT 1,
    target     TEXT NOT NULL CHECK (target IN
                   ('url', 'request_header', 'request_body', 'response_header', 'response_body')),
    match      TEXT NOT NULL,
    replace    TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL
);;

CREATE TABLE reachability (
    id         TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    cve        TEXT NOT NULL,
    package    TEXT NOT NULL DEFAULT '',
    reachable  INTEGER NOT NULL,         -- 0 = imported/uncalled, 1 = called (in the call graph)
    source     TEXT NOT NULL DEFAULT '', -- the analyzer that produced the verdict, e.g. govulncheck
    updated_at TEXT NOT NULL,
    UNIQUE (project_id, cve)
);;

CREATE TABLE reports (
    id          TEXT PRIMARY KEY,
    project_id  TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    template_id TEXT NOT NULL,
    format      TEXT NOT NULL,
    title       TEXT NOT NULL DEFAULT '',
    artifact_id TEXT NOT NULL REFERENCES artifacts(id),
    created_at  TEXT NOT NULL
);;

CREATE TABLE routes (
    id           TEXT PRIMARY KEY,
    project_id   TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    method       TEXT NOT NULL DEFAULT '',   -- GET/POST/... or '' = any/unknown
    path         TEXT NOT NULL,              -- declared route path, e.g. /users/{id}
    handler_file TEXT NOT NULL DEFAULT '',   -- source file where the route/handler is declared
    handler_line INTEGER NOT NULL DEFAULT 0,
    framework    TEXT NOT NULL DEFAULT '',   -- flask / express / net-http / gin / ...
    source       TEXT NOT NULL DEFAULT '',   -- the capability that extracted it
    observed     INTEGER NOT NULL DEFAULT 0, -- 1 = matched captured traffic (confirmed exposed)
    updated_at   TEXT NOT NULL,
    UNIQUE (project_id, method, path)
);;

CREATE TABLE schedules (
    id               TEXT PRIMARY KEY,
    project_id       TEXT NOT NULL,
    playbook_id      TEXT NOT NULL,
    interval_seconds INTEGER NOT NULL,
    enabled          INTEGER NOT NULL DEFAULT 1,
    last_run_at      TEXT,
    next_run_at      TEXT NOT NULL,
    created_at       TEXT NOT NULL
);;

CREATE TABLE scope_entries (
    id         TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    kind       TEXT NOT NULL CHECK (kind IN ('host', 'domain', 'cidr')),
    value      TEXT NOT NULL,
    created_at TEXT NOT NULL
);;

CREATE TABLE sessions (
    id                    TEXT PRIMARY KEY,
    project_id            TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    kind                  TEXT NOT NULL DEFAULT 'terminal' CHECK (kind IN ('terminal')),
    runner                TEXT NOT NULL DEFAULT '',
    container             TEXT NOT NULL DEFAULT '',
    image                 TEXT NOT NULL DEFAULT '',
    status                TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'closed', 'error')),
    actor                 TEXT NOT NULL DEFAULT '',
    transcript_artifact_id TEXT REFERENCES artifacts(id),
    error                 TEXT NOT NULL DEFAULT '',
    created_at            TEXT NOT NULL,
    closed_at             TEXT
);;

CREATE TABLE tasks (
    id                 TEXT PRIMARY KEY,
    capability_id      TEXT NOT NULL,
    capability_version TEXT NOT NULL,
    application_id     TEXT REFERENCES applications(id) ON DELETE SET NULL,
    asset_id           TEXT REFERENCES assets(id) ON DELETE SET NULL,
    actor              TEXT NOT NULL,
    runner             TEXT NOT NULL,
    params             TEXT NOT NULL DEFAULT '{}',
    status             TEXT NOT NULL DEFAULT 'pending'
                           CHECK (status IN ('pending', 'running', 'succeeded', 'failed')),
    exit_code          INTEGER,
    error              TEXT NOT NULL DEFAULT '',
    created_at         TEXT NOT NULL,
    started_at         TEXT,
    finished_at        TEXT
, project_id TEXT REFERENCES projects(id), secret_refs TEXT NOT NULL DEFAULT '', target_dir  TEXT NOT NULL DEFAULT '', attempts    INTEGER NOT NULL DEFAULT 0, runner_target TEXT NOT NULL DEFAULT '');;

CREATE TABLE threads (
    id               TEXT PRIMARY KEY,
    project_id       TEXT REFERENCES projects(id) ON DELETE CASCADE,
    parent_thread_id TEXT REFERENCES threads(id) ON DELETE SET NULL,
    fork_seq         INTEGER, -- parent message seq this thread forked at
    title            TEXT NOT NULL DEFAULT '',
    status           TEXT NOT NULL DEFAULT 'active'
                         CHECK (status IN ('active', 'awaiting_approval', 'done', 'error')),
    provider         TEXT NOT NULL DEFAULT '',
    created_at       TEXT NOT NULL,
    updated_at       TEXT NOT NULL
, agent_type TEXT NOT NULL DEFAULT 'generalist');;

CREATE TABLE usage_records (
    id            TEXT PRIMARY KEY,
    project_id    TEXT REFERENCES projects(id) ON DELETE CASCADE, -- nullable: not every run is project-scoped
    thread_id     TEXT NOT NULL DEFAULT '',
    provider      TEXT NOT NULL,                                  -- vendor/type: anthropic | openai | ollama | claude-cli | …
    model         TEXT NOT NULL DEFAULT '',
    input_tokens  INTEGER NOT NULL DEFAULT 0,
    output_tokens INTEGER NOT NULL DEFAULT 0,
    created_at    TEXT NOT NULL
, agent_type TEXT NOT NULL DEFAULT '');;

CREATE INDEX idx_applications_project ON applications(project_id);;

CREATE INDEX idx_approvals_status ON approvals(status);;

CREATE INDEX idx_approvals_thread ON approvals(thread_id);;

CREATE INDEX idx_artifacts_sha256 ON artifacts(sha256);;

CREATE INDEX idx_artifacts_task ON artifacts(task_id);;

CREATE INDEX idx_assets_application ON assets(application_id);;

CREATE INDEX idx_context_items_project ON context_items(project_id);;

CREATE INDEX idx_corpus_chunks_project ON corpus_chunks(project_id);;

CREATE INDEX idx_corpus_chunks_source ON corpus_chunks(project_id, source_kind, source_id);;

CREATE INDEX idx_coverage_observations_item ON coverage_observations(project_id, item_id);;

CREATE INDEX idx_coverage_observations_obs ON coverage_observations(observation_id);;

CREATE INDEX idx_disposition_rules_project ON disposition_rules(project_id);;

CREATE INDEX idx_external_links_finding ON external_links(finding_id);;

CREATE INDEX idx_finding_observations_observation ON finding_observations(observation_id);;

CREATE INDEX idx_findings_application ON findings(application_id);;

CREATE INDEX idx_http_exchanges_project ON http_exchanges(project_id, created_at);;

CREATE INDEX idx_investigation_vulns_inv ON investigation_vulns(investigation_id);;

CREATE INDEX idx_investigations_project ON investigations(project_id, status);;

CREATE INDEX idx_messages_thread ON messages(thread_id);;

CREATE INDEX idx_notifications_unread ON notifications(read, created_at);;

CREATE INDEX idx_observations_artifact ON observations(artifact_id);;

CREATE INDEX idx_observations_fingerprint ON observations(project_id, fingerprint);;

CREATE INDEX idx_observations_review ON observations(review_state);;

CREATE INDEX idx_observations_task ON observations(task_id);;

CREATE INDEX idx_plan_steps_plan ON plan_steps(plan_id, seq);;

CREATE INDEX idx_plans_project ON plans(project_id, created_at);;

CREATE INDEX idx_playbook_run_tasks_run ON playbook_run_tasks(run_id);;

CREATE INDEX idx_playbook_runs_asset ON playbook_runs(asset_id);;

CREATE INDEX idx_project_targets_target ON project_targets(target_id);;

CREATE INDEX idx_projects_group ON projects(group_id);;

CREATE INDEX idx_projects_organization ON projects(organization_id);;

CREATE INDEX idx_proxy_rules_project ON proxy_rules(project_id, created_at);;

CREATE INDEX idx_reachability_project ON reachability(project_id);;

CREATE INDEX idx_reports_project ON reports(project_id, created_at);;

CREATE INDEX idx_routes_handler ON routes(project_id, handler_file);;

CREATE INDEX idx_routes_project ON routes(project_id);;

CREATE INDEX idx_schedules_due ON schedules(enabled, next_run_at);;

CREATE INDEX idx_scope_entries_project ON scope_entries(project_id);;

CREATE INDEX idx_sessions_project ON sessions(project_id, created_at);;

CREATE INDEX idx_tasks_application ON tasks(application_id);;

CREATE INDEX idx_tasks_asset ON tasks(asset_id);;

CREATE INDEX idx_tasks_capability ON tasks(capability_id);;

CREATE INDEX idx_tasks_pending ON tasks(status, created_at);;

CREATE INDEX idx_tasks_project ON tasks(project_id);;

CREATE INDEX idx_threads_parent ON threads(parent_thread_id);;

CREATE INDEX idx_threads_project ON threads(project_id);;

CREATE INDEX idx_usage_project ON usage_records(project_id, created_at);;
